text:
 *
 * Gets the suggested text to be shown when an imip item has been processed.
 * This text is ready localized and can be displayed to the user.
 *
 * @param {number} aStatus - The status of the processing (i.e NS_OK, an error code)
 * @param {number} aOperationType - An operation type from calIOperationListener
 * @returns {string} The suggested text.
 */
getCompleteText(aStatus, aOperationType) {
  let text = "";
  if (Components.isSuccessCode(aStatus)) {
    switch (aOperationType) {
      case Ci.calIOperationListener.ADD:
        text = lazy.l10n.formatValueSync("imip-added-item-to-cal");
        break;
      case Ci.calIOperationListener.MODIFY:
        text = lazy.l10n.formatValueSync("imip-updated-item");
        break;
      case Ci.calIOperationListener.DELETE:
        text = lazy.l10n.formatValueSync("imip-canceled-item");
        break;
    }
  } else {
    text = lazy.l10n.formatValueSync("imip-bar-processing-failed", {
      status: aStatus.toString(16),
    });
  }
  return text;
